import { readdirSync, readFileSync } from 'node:fs';
import { join } from 'node:path';

import type { SoapCatalog } from '../src/catalog/catalog-types.js';
import { XmlReader } from '../src/xml/xml-reader.js';
import { CatalogBuilder, type ServiceDocuments } from './catalog-builder.js';
import { SERVICES, type ServiceDefinition } from './service-registry.js';

const HEADER = [
  '// Generated by `npm run generate` from vendor/twinfield. Do not edit by hand.',
  "import type { SoapCatalog } from './catalog-types.js';",
  '',
].join('\n');

export class CatalogGenerator {
  private readonly reader = new XmlReader();

  constructor(
    private readonly vendorDirectory: string,
    private readonly services: readonly ServiceDefinition[] = SERVICES,
  ) {}

  catalog(): SoapCatalog {
    return new CatalogBuilder().build(this.services.map((service) => this.documents(service)));
  }

  source(): string {
    return `${HEADER}\nexport const SOAP_CATALOG: SoapCatalog = ${JSON.stringify(this.catalog(), null, 2)};\n`;
  }

  private documents(definition: ServiceDefinition): ServiceDocuments {
    return {
      definition,
      wsdl: this.read(join('wsdl', definition.wsdlFile)),
      schemas: this.schemaFiles(definition).map((file) => this.read(join('xsd', file))),
    };
  }

  /** WCF services publish their types as separate `?xsd=xsdN` files, named after the service. */
  private schemaFiles(definition: ServiceDefinition): string[] {
    const service = definition.wsdlFile.replace(/\.wsdl$/, '').toLowerCase();

    return readdirSync(join(this.vendorDirectory, 'xsd'))
      .filter((file) => file.toLowerCase().startsWith(`${service}_xsd_`))
      .sort();
  }

  private read(path: string): ReturnType<XmlReader['read']> {
    return this.reader.read(readFileSync(join(this.vendorDirectory, path), 'utf8'));
  }
}
